-- =====================================================================
-- TBL_BIZI_MST 사업장 주소·택배정보 일괄 반영 — SRM(삼성웰스토리) [사업장별 비상연락망] 캡쳐분 (2026-08-06)
--   원천 : SRM 상황관리 ▸ 사업장별 비상연락망 (사업장명 '호호' 검색, 1~170행)
--          → '택배정보(택배주소·수령자·전화·휴대폰)' 가 있는 49건. 배송처 주소·우편번호도 함께 옮긴다.
--   저장 규칙 (사용자 확정 2026-08-06)
--     · ADDR / ZIPCD      = SRM '배송처 주소' · 우편번호
--     · PARCEL_ADDR       = SRM '택배 주소'  ← 조회·엑셀에서 이 값이 우선(없으면 ADDR)
--     · PARCEL_NM/TEL/HP  = SRM 수령자 · 전화번호 · 휴대폰번호
--     · 사업장이 없으면 신규 등록, 있으면 SRM 값으로 덮어씀(SRM 이 이 정보의 원천)
--     · 지점 없는 이름('호호솥밥')만 SRM 이름으로 보정 — A0376534·A0396385·A0404585
--       (이름이 같아 매칭이 안 되던 건들)
--     · PARCEL_FEE(운임)는 건드리지 않는다 — 사업장관리/택배출고관리에서 입력
--   ★실행 주의: 이 배치는 임시표(#P)를 쓰므로 한 연결에서 통째로 실행해야 한다.
--     중간에 Statement 를 닫으면 뒤 문장이 취소된다(2026-08-06 1차 실패 원인).
-- =====================================================================
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID('dbo.TBL_BIZI_MST') AND name='PARCEL_NM')
BEGIN
    ALTER TABLE dbo.TBL_BIZI_MST ADD PARCEL_NM NVARCHAR(100) NULL;
END
GO

-- ★COLLATE DATABASE_DEFAULT 필수 — tempdb 는 SQL_Latin1_General, 업무DB는 Korean_Wansung 이라
--   붙이지 않으면 JOIN 에서 "데이터 정렬 충돌" 로 배치가 통째로 실패한다(2026-08-06 확인).
CREATE TABLE #P (BIZ_CD NVARCHAR(40)  COLLATE DATABASE_DEFAULT, BIZ_NM NVARCHAR(200) COLLATE DATABASE_DEFAULT,
                 D_ADDR NVARCHAR(400) COLLATE DATABASE_DEFAULT, ZIP    NVARCHAR(20)  COLLATE DATABASE_DEFAULT,
                 P_ADDR NVARCHAR(400) COLLATE DATABASE_DEFAULT, P_NM   NVARCHAR(100) COLLATE DATABASE_DEFAULT,
                 P_TEL  NVARCHAR(60)  COLLATE DATABASE_DEFAULT, P_HP   NVARCHAR(60)  COLLATE DATABASE_DEFAULT);


-- ① 없는 사업장 신규 등록 (배송처 주소·우편번호·택배정보 함께)
        PARCEL_ADDR, PARCEL_NM, PARCEL_TEL, PARCEL_HP, REG_DTTM, REG_USER)
SELECT 'W1234567', p.BIZ_CD, 1, 'Y', p.BIZ_NM, p.D_ADDR, p.ZIP,
       p.P_ADDR, NULLIF(p.P_NM,N''), NULLIF(p.P_TEL,N''), NULLIF(p.P_HP,N''), GETDATE(), N'srm_parcel'
  FROM #P p
 WHERE NOT EXISTS (SELECT 1 FROM dbo.TBL_BIZI_MST b WHERE b.BIZ_CD = p.BIZ_CD);

-- ② 기존 사업장 — 배송처 주소·우편번호 + 택배정보 반영
UPDATE b
   SET b.ADDR        = p.D_ADDR,
       b.ZIPCD       = p.ZIP,
       b.PARCEL_ADDR = p.P_ADDR,
       b.PARCEL_NM   = NULLIF(p.P_NM,  N''),
       b.PARCEL_TEL  = NULLIF(p.P_TEL, N''),
       b.PARCEL_HP   = NULLIF(p.P_HP,  N''),
       b.BIZ_NM      = CASE WHEN LTRIM(RTRIM(ISNULL(b.BIZ_NM,''))) = N'호호솥밥' THEN p.BIZ_NM ELSE b.BIZ_NM END,
       b.ACTION_YN   = 'Y',
       b.UPD_DTTM    = GETDATE(), b.UPD_USER = N'srm_parcel'
  FROM dbo.TBL_BIZI_MST b
  JOIN #P p ON p.BIZ_CD = b.BIZ_CD
 WHERE ISNULL(b.REG_USER,'') <> N'srm_parcel';   -- ①에서 방금 넣은 건 제외

SELECT COUNT(*) AS srm_total FROM #P;
SELECT COUNT(*) AS inserted FROM dbo.TBL_BIZI_MST WHERE REG_USER = N'srm_parcel';
SELECT COUNT(*) AS parcel_rows FROM dbo.TBL_BIZI_MST WHERE ISNULL(PARCEL_ADDR,'') <> '';
DROP TABLE #P;
